//! Intermediate Representation (IR) types for prompt files.

use serde::{Deserialize, Serialize};

/// The intermediate representation of a prompt file.
///
/// Generated by the SLM analysis and cached by document URI + version.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PromptIR {
    /// Document URI (e.g., "file:///path/to/prompt.rtpl")
    pub uri: String,
    /// Document version for cache invalidation
    pub version: i32,
    /// Extracted nodes (rules, conditions, breakpoints, etc.)
    pub nodes: Vec<IRNode>,
    /// Parser metadata
    #[serde(skip_serializing_if = "Option::is_none")]
    pub meta: Option<IRMeta>,
}

impl PromptIR {
    /// Create a new empty IR for a document.
    pub fn new(uri: impl Into<String>, version: i32) -> Self {
        Self {
            uri: uri.into(),
            version,
            nodes: Vec::new(),
            meta: None,
        }
    }

    /// Find a node by its ID.
    pub fn find_node(&self, id: &str) -> Option<&IRNode> {
        self.nodes.iter().find(|n| n.id == id)
    }

    /// Get all nodes of a specific kind.
    pub fn nodes_by_kind(&self, kind: IRKind) -> Vec<&IRNode> {
        self.nodes.iter().filter(|n| n.kind == kind).collect()
    }

    /// Get all rule nodes.
    pub fn rules(&self) -> Vec<&IRNode> {
        self.nodes_by_kind(IRKind::Rule)
    }

    /// Get all condition nodes.
    pub fn conditions(&self) -> Vec<&IRNode> {
        self.nodes_by_kind(IRKind::Condition)
    }

    /// Get all breakpoint nodes.
    pub fn breakpoints(&self) -> Vec<&IRNode> {
        self.nodes_by_kind(IRKind::Breakpoint)
    }

    /// Get all skill instruction nodes.
    pub fn skill_instructions(&self) -> Vec<&IRNode> {
        self.nodes_by_kind(IRKind::SkillInstruction)
    }

    /// Get all skill constraint nodes.
    pub fn skill_constraints(&self) -> Vec<&IRNode> {
        self.nodes_by_kind(IRKind::SkillConstraint)
    }
}

/// A single node in the IR tree.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IRNode {
    /// Unique identifier (e.g., "RULE:STYLE_CASUAL")
    pub id: String,
    /// Node type
    pub kind: IRKind,
    /// Human-readable label
    #[serde(skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
    /// Source location
    pub range: TextRange,
    /// Additional metadata
    #[serde(default)]
    pub meta: IRNodeMeta,
}

/// The type of IR node.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum IRKind {
    Rule,
    Condition,
    Breakpoint,
    Section,
    Directive,
    /// A behavioral instruction extracted from a skill body
    SkillInstruction,
    /// A constraint from skill frontmatter or inferred from instructions
    SkillConstraint,
}

impl std::fmt::Display for IRKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            IRKind::Rule => write!(f, "Rule"),
            IRKind::Condition => write!(f, "Condition"),
            IRKind::Breakpoint => write!(f, "Breakpoint"),
            IRKind::Section => write!(f, "Section"),
            IRKind::Directive => write!(f, "Directive"),
            IRKind::SkillInstruction => write!(f, "Instruction"),
            IRKind::SkillConstraint => write!(f, "Constraint"),
        }
    }
}

/// Source location range (0-indexed lines and columns).
#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct TextRange {
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
}

impl TextRange {
    pub fn new(start_line: u32, start_col: u32, end_line: u32, end_col: u32) -> Self {
        Self {
            start_line,
            start_col,
            end_line,
            end_col,
        }
    }

    /// Check if a position is within this range.
    pub fn contains(&self, line: u32, col: u32) -> bool {
        if line < self.start_line || line > self.end_line {
            return false;
        }
        if line == self.start_line && col < self.start_col {
            return false;
        }
        if line == self.end_line && col > self.end_col {
            return false;
        }
        true
    }
}

/// Additional metadata for an IR node.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct IRNodeMeta {
    /// Category (e.g., "style", "safety")
    #[serde(skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,
    /// Trigger conditions
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub triggers: Vec<String>,
    /// Reference to a condition (for breakpoints)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub condition_ref: Option<String>,
    /// Priority level
    #[serde(skip_serializing_if = "Option::is_none")]
    pub priority: Option<i32>,
    /// Whether this node was inferred by the SLM
    #[serde(default)]
    pub inferred: bool,
}

/// Metadata about the IR generation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IRMeta {
    /// Version of the parser/prompt
    pub parser_version: String,
    /// Confidence score (0.0-1.0)
    pub confidence: f32,
    /// Engine used ("llm", "regex", etc.)
    pub engine: String,
    /// Any warnings during parsing
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub warnings: Vec<String>,
}

impl Default for IRMeta {
    fn default() -> Self {
        Self {
            parser_version: "1.0".to_string(),
            confidence: 1.0,
            engine: "llm".to_string(),
            warnings: Vec::new(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ir_find_node() {
        let ir = PromptIR {
            uri: "file:///test.rtpl".to_string(),
            version: 1,
            nodes: vec![IRNode {
                id: "RULE:GREETING".to_string(),
                kind: IRKind::Rule,
                label: Some("Greeting rule".to_string()),
                range: TextRange::new(0, 0, 1, 0),
                meta: IRNodeMeta::default(),
            }],
            meta: None,
        };

        assert!(ir.find_node("RULE:GREETING").is_some());
        assert!(ir.find_node("RULE:NONEXISTENT").is_none());
    }

    #[test]
    fn test_text_range_contains() {
        let range = TextRange::new(5, 0, 10, 50);

        assert!(range.contains(7, 25));
        assert!(range.contains(5, 0));
        assert!(range.contains(10, 50));
        assert!(!range.contains(4, 0));
        assert!(!range.contains(11, 0));
        assert!(range.contains(5, 0)); // start is inclusive
    }

    #[test]
    fn test_ir_serialization() {
        let ir = PromptIR::new("file:///test.rtpl", 1);
        let json = serde_json::to_string(&ir).unwrap();
        assert!(json.contains("file:///test.rtpl"));
    }
}
